import app from 'flarum/admin/app';
import Component from 'flarum/common/Component';
import Button from 'flarum/common/components/Button';
import Icon from 'flarum/common/components/Icon';
import LoadingIndicator from 'flarum/common/components/LoadingIndicator';
import extractText from 'flarum/common/utils/extractText';
import { categories, deleteCategory, orderCategories, saveCategory } from '../common/api';
import Sortable from '../common/sortable';
const t = (key, params = {}) => app.translator.trans(`ernestdefoe-syllabus.admin.categories.${key}`, params);

/** Course categories: add, rename, remove, and drag into order (arrow keys on the handle do the same). */
export default class CategoriesSetting extends Component {
  list = null;
  name = '';
  busy = false;
  oninit(vnode) {
    super.oninit(vnode);
    this.sorter = new Sortable(() => this.list || [], () => this.order(), extractText(t('sortable')));
    categories().then(({
      data
    }) => {
      this.list = data;
      m.redraw();
    });
  }
  view() {
    return m("div", {
      className: "Form-group SyllabusCategories"
    }, m("label", null, t('title')), m("div", {
      className: "helpText"
    }, t('help')), !this.list ? m(LoadingIndicator, null) : m("ol", {
      className: "SyllabusCategories-list",
      "data-sortable": true
    }, this.list.map((cat, index) => m("li", {
      key: cat.id,
      className: 'SyllabusCategories-row' + (this.sorter.dragging === index ? ' is-dragging' : '')
    }, m("span", Object.assign({
      className: "SyllabusCategories-handle"
    }, this.sorter.handle(index), {
      "aria-label": extractText(t('move', {
        name: cat.name
      }))
    }), m(Icon, {
      name: "fas fa-grip-vertical"
    })), m("input", {
      className: "FormControl",
      value: cat.name,
      maxlength: 100,
      "aria-label": extractText(t('name')),
      oninput: e => cat.name = e.target.value,
      onchange: () => saveCategory({
        name: cat.name
      }, cat.id)
    }), m("span", {
      className: "helpText"
    }, t('courses', {
      count: cat.courseCount
    })), m(Button, {
      className: "Button Button--icon Button--link",
      icon: "fas fa-trash",
      "aria-label": extractText(t('delete')),
      onclick: () => {
        if (!confirm(extractText(t('delete_confirm', {
          name: cat.name
        })))) return;
        deleteCategory(cat.id).then(() => {
          this.list = (this.list || []).filter(c => c.id !== cat.id);
          m.redraw();
        });
      }
    })))), m("div", {
      className: "SyllabusCategories-add"
    }, m("input", {
      className: "FormControl",
      maxlength: 100,
      placeholder: extractText(t('new')),
      "aria-label": extractText(t('new')),
      value: this.name,
      oninput: e => this.name = e.target.value,
      onkeydown: e => e.key === 'Enter' && (e.preventDefault(), this.add())
    }), m(Button, {
      className: "Button",
      icon: "fas fa-plus",
      loading: this.busy,
      disabled: !this.name.trim(),
      onclick: () => this.add()
    }, t('add'))));
  }
  add() {
    if (!this.name.trim()) return;
    this.busy = true;
    saveCategory({
      name: this.name.trim()
    }).then(({
      data
    }) => {
      this.list = data;
      this.name = '';
    }).finally(() => {
      this.busy = false;
      m.redraw();
    });
  }
  order() {
    orderCategories((this.list || []).map(c => c.id)).then(({
      data
    }) => {
      this.list = data;
      m.redraw();
    });
  }
}